        "scenarios": list(first_scenarios),
        "data": rows,
    }


_MATRIX_EVOLUTION_SCHEMA = "climate-grid/cme-v1"
_MATRIX_EVOLUTION_ITEM_KEYS = ("period", "models")


def matrix_evolution(items) -> dict:
    """Track per-model :func:`converge_matrix` evolution across periods.

    ``items`` must be a list of at least two mappings, each with exactly
    the keys ``period, models`` in that order.  ``period`` is a non-empty
    str that is unique across items and ``models`` is a non-empty mapping
    of non-empty str model names to complete :func:`converge_matrix`
    results (schema ``climate-grid/cvm-v1``); every matrix is validated
    against that contract.  All items must share the same model key
    order and all matrices must share the same ``tolerance``, the same
    ``layers`` and the same scenario order, taken from the first item's
    first model.

    For every adjacent pair of periods (in item order), every model (in
    the shared model order) and every scenario (in the shared scenario
    order) the row ``from`` and ``to`` are the earlier and later
    ``state``.  When both rows have an ``interval``, ``interval`` is
    ``[later lo − earlier lo, later hi − earlier hi]``; otherwise it is
    ``None``.  ``rank`` is the later ``rank`` minus the earlier ``rank``
    when both are present, else ``None``.

    The returned mapping uses the key order ``schema, periods, models,
    scenarios, data``; ``schema`` is ``climate-grid/cme-v1``,
    ``periods`` lists the item periods in order, ``models`` the shared
    model order and ``scenarios`` the shared scenario order.  ``data``
    iterates the adjacent period pairs in order, then the models, then
    the scenarios; each row uses the key order ``left, right, model,
    scenario, from, to, interval, rank`` where ``left`` and ``right``
    are the earlier and later period.  ``rank`` is an int and every
    output float is ``round(x, 12)`` with negative zero normalized to
    ``0.0``.  The input is not modified.

    Raises ``TypeError`` for wrong container/item/argument types and
    ``ValueError`` for any other contract violation.
    """
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if len(items) < 2:
        raise ValueError("items must contain at least 2 items")

    periods = []
    validated: list[dict] = []
    seen_periods: set[str] = set()
    for index, item in enumerate(items):
        where = f"items[{index}]"
        if not isinstance(item, dict):
            raise TypeError(f"{where} must be a dict")
        if tuple(item.keys()) != _MATRIX_EVOLUTION_ITEM_KEYS:
            raise ValueError(
                f"{where} must have exactly the keys period, models in "
                "order"
            )

        period = item["period"]
        if not isinstance(period, str):
            raise TypeError(f"{where}.period must be a str")
        if period == "":
            raise ValueError(f"{where}.period must be non-empty")
        if period in seen_periods:
            raise ValueError(f"duplicate items period: {period!r}")
        seen_periods.add(period)

        models = item["models"]
        if not isinstance(models, dict):
            raise TypeError(f"{where}.models must be a dict")
        if len(models) == 0:
            raise ValueError(f"{where}.models must be non-empty")

        lookups = {}
        for model, matrix in models.items():
            if not isinstance(model, str):
                raise TypeError(f"{where}.models keys must be str")
            if model == "":
                raise ValueError(f"{where}.models keys must be non-empty")
            tolerance, layers, data = _validate_converge_matrix(
                matrix, where=f"{where}.models[{model!r}]"
            )
            scenarios = [row["scenario"] for row in data]
            if not validated and not lookups:
                first_tolerance = tolerance
                first_layers = layers
                first_scenarios = scenarios
            else:
                if tolerance != first_tolerance:
                    raise ValueError(
                        "all matrices must share the same tolerance, "
                        "taken from the first item"
                    )
                if layers != first_layers:
                    raise ValueError(
                        "all matrices must share the same layers, "
                        "taken from the first item"
                    )
                if scenarios != first_scenarios:
                    raise ValueError(
                        "all matrices must share the same scenario "
                        "order, taken from the first item"
                    )
            lookups[model] = {row["scenario"]: row for row in data}

        if not validated:
            first_models = list(models.keys())
        elif list(models.keys()) != first_models:
            raise ValueError(
                "all items must share the same model order, taken from "
                "the first item"
            )

        periods.append(period)
        validated.append(lookups)

    rows = []
    for left_index in range(len(items) - 1):
        earlier = validated[left_index]
        later = validated[left_index + 1]
        for model in first_models:
            for scenario in first_scenarios:
                before = earlier[model][scenario]
                after = later[model][scenario]
                if (
                    before["interval"] is not None
                    and after["interval"] is not None
                ):
                    interval = [
                        _round_output(
                            after["interval"][0] - before["interval"][0]
                        ),
                        _round_output(
                            after["interval"][1] - before["interval"][1]
                        ),
                    ]
                else:
                    interval = None
                if before["rank"] is not None and after["rank"] is not None:
                    rank = after["rank"] - before["rank"]
                else:
                    rank = None
                rows.append(
                    {
                        "left": periods[left_index],
                        "right": periods[left_index + 1],
                        "model": model,
                        "scenario": scenario,
                        "from": before["state"],
                        "to": after["state"],
                        "interval": interval,
                        "rank": rank,
                    }
                )

    return {
        "schema": _MATRIX_EVOLUTION_SCHEMA,
        "periods": periods,
        "models": list(first_models),
        "scenarios": list(first_scenarios),
        "data": rows,
    }

_CONVERGE_MATRIX_OUTPUT_KEYS = ("schema", "tolerance", "layers", "data")
_CONVERGE_MATRIX_LAYER_KEYS = ("element", "region")
_CONVERGE_MATRIX_ROW_KEYS = (
    "scenario",
    "count",
    "states",
    "interval",
    "state",
    "rank",
)
_CONVERGE_MATRIX_STATE_KEYS = ("stable", "uncertain", "divergent")
_COMPARE_MATRIX_SCHEMA = "climate-grid/cmc-v1"
_COMPARE_MATRIX_ITEM_KEYS = ("name", "matrix")


def _validate_converge_matrix(
    result: Any, *, where: str = "matrix"
) -> tuple[float, list, list]:
    """Validate a complete :func:`converge_matrix` result.

    Returns the tolerance, the ``layers`` rows and the ``data`` rows.
    Rows with an interval must carry the state implied by the shared
    tolerance and ranks must be 1..n assigned by ascending interval
    ``hi`` with ties in scenario order.
    """
    if not isinstance(result, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _CONVERGE_MATRIX_OUTPUT_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, tolerance, layers, "
            "data in order"
        )

    schema = result["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _CONVERGE_MATRIX_SCHEMA:
        raise ValueError(f"{where}.schema must be {_CONVERGE_MATRIX_SCHEMA!r}")

    tolerance = result["tolerance"]
    if not isinstance(tolerance, (int, float)) or isinstance(tolerance, bool):
        raise TypeError(f"{where}.tolerance must be a non-bool number")
    if not _is_finite(tolerance):
        raise ValueError(f"{where}.tolerance must be finite")
    if tolerance < 0:
        raise ValueError(f"{where}.tolerance must be non-negative")

    layers = result["layers"]
    if not isinstance(layers, list):
        raise TypeError(f"{where}.layers must be a list")
    if len(layers) == 0:
        raise ValueError(f"{where}.layers must be non-empty")
    seen_combinations: set[tuple[str, str]] = set()
    validated_layers = []
    for index, layer in enumerate(layers):
        layer_where = f"{where}.layers[{index}]"
        if not isinstance(layer, dict):
            raise TypeError(f"{layer_where} must be a dict")
        if tuple(layer.keys()) != _CONVERGE_MATRIX_LAYER_KEYS:
            raise ValueError(
                f"{layer_where} must have exactly the keys element, region "
                "in order"
            )
        element = layer["element"]
        if not isinstance(element, str):
            raise TypeError(f"{layer_where}.element must be a str")
        if element == "":
            raise ValueError(f"{layer_where}.element must be non-empty")
        region = layer["region"]
        if not isinstance(region, str):
            raise TypeError(f"{layer_where}.region must be a str")
        if region == "":
            raise ValueError(f"{layer_where}.region must be non-empty")
        combination = (element, region)
        if combination in seen_combinations:
            raise ValueError(
                f"duplicate {where}.layers element/region combination: "
                f"{element!r}, {region!r}"
            )
        seen_combinations.add(combination)
        validated_layers.append({"element": element, "region": region})

    data = result["data"]
    if not isinstance(data, list):
        raise TypeError(f"{where}.data must be a list")
    if len(data) == 0:
        raise ValueError(f"{where}.data must be non-empty")

    seen_scenarios: set[str] = set()
    ranked: list[tuple[float, int, int]] = []
    for index, row in enumerate(data):
        row_where = f"{where}.data[{index}]"
        if not isinstance(row, dict):
            raise TypeError(f"{row_where} must be a dict")
        if tuple(row.keys()) != _CONVERGE_MATRIX_ROW_KEYS:
            raise ValueError(
                f"{row_where} must have exactly the keys scenario, count, "
                "states, interval, state, rank in order"
            )

        scenario = row["scenario"]
        if not isinstance(scenario, str):
            raise TypeError(f"{row_where}.scenario must be a str")
        if scenario == "":
            raise ValueError(f"{row_where}.scenario must be non-empty")
        if scenario in seen_scenarios:
            raise ValueError(f"duplicate {where}.data scenario: {scenario!r}")
        seen_scenarios.add(scenario)

        count = row["count"]
        if not isinstance(count, int) or isinstance(count, bool):
            raise TypeError(f"{row_where}.count must be a non-bool int")
        if not 0 <= count <= len(validated_layers):
            raise ValueError(
                f"{row_where}.count must be between 0 and "
                f"{len(validated_layers)}"
            )

        states = row["states"]
        if not isinstance(states, dict):
            raise TypeError(f"{row_where}.states must be a dict")
        if tuple(states.keys()) != _CONVERGE_MATRIX_STATE_KEYS:
            raise ValueError(
                f"{row_where}.states must have exactly the keys stable, "
                "uncertain, divergent in order"
            )
        for state_name, state_count in states.items():
            if not isinstance(state_count, int) or isinstance(
                state_count, bool
            ):
                raise TypeError(
                    f"{row_where}.states[{state_name!r}] must be a non-bool "
                    "int"
                )
            if state_count < 0:
                raise ValueError(
                    f"{row_where}.states[{state_name!r}] must be "
                    "non-negative"
                )
        if sum(states.values()) != count:
            raise ValueError(
                f"{row_where}.states counts must sum to {row_where}.count"
            )

        interval = row["interval"]
        state = row["state"]
        rank = row["rank"]
        if interval is None or state is None or rank is None:
            if interval is not None or state is not None or rank is not None:
                raise ValueError(
                    f"{row_where}: interval, state and rank must be all "
                    "None or all present"
                )
            continue

        if count == 0:
            raise ValueError(
                f"{row_where}: interval, state and rank must be None when "
                "count is zero"
            )

def _validate_rank_transitions(result: Any, *, where: str = "result") -> tuple:
    if not isinstance(result, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _RANK_TRANSITIONS_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, baseline, configs, "
            "scenarios, data, transitions in order"
        )

    schema = result["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _RANK_TRANSITIONS_SCHEMA:
        raise ValueError(f"{where}.schema must be {_RANK_TRANSITIONS_SCHEMA!r}")

    baseline = result["baseline"]
    if not isinstance(baseline, str):
        raise TypeError(f"{where}.baseline must be a str")
    if baseline == "":
        raise ValueError(f"{where}.baseline must be non-empty")

    configs = result["configs"]
    if not isinstance(configs, list):
        raise TypeError(f"{where}.configs must be a list")
    if len(configs) == 0:
        raise ValueError(f"{where}.configs must be non-empty")
    seen_configs: set[str] = set()
    for index, config in enumerate(configs):
        if not isinstance(config, str):
            raise TypeError(f"{where}.configs[{index}] must be a str")
        if config == "":
            raise ValueError(f"{where}.configs[{index}] must be non-empty")
        if config in seen_configs:
            raise ValueError(f"duplicate {where}.configs entry: {config!r}")
        seen_configs.add(config)

    scenarios = result["scenarios"]
    if not isinstance(scenarios, list):
        raise TypeError(f"{where}.scenarios must be a list")
    if len(scenarios) == 0:
        raise ValueError(f"{where}.scenarios must be non-empty")
    seen_scenarios: set[str] = set()
    for index, scenario in enumerate(scenarios):
        if not isinstance(scenario, str):
            raise TypeError(f"{where}.scenarios[{index}] must be a str")
        if scenario == "":
            raise ValueError(f"{where}.scenarios[{index}] must be non-empty")
        if scenario in seen_scenarios:
            raise ValueError(f"duplicate {where}.scenarios entry: {scenario!r}")
        seen_scenarios.add(scenario)

    data = result["data"]
    if not isinstance(data, list):
        raise TypeError(f"{where}.data must be a list")
    expected_rows = len(configs) * len(scenarios)
    if len(data) != expected_rows:
        raise ValueError(
            f"{where}.data must have {expected_rows} rows "
            "(one per config/scenario combination, in "
            "config-then-scenario order)"
        )

    row_index = 0
    valid_total = 0
    for config in configs:
        for scenario in scenarios:
            row_where = f"{where}.data[{row_index}]"
            row = data[row_index]
            if not isinstance(row, dict):
                raise TypeError(f"{row_where} must be a dict")
            if tuple(row.keys()) != _RANK_TRANSITIONS_ROW_KEYS:
                raise ValueError(
                    f"{row_where} must have exactly the keys config, scenario, "
                    "baseline_rank, rank, delta in order"
                )

            if not isinstance(row["config"], str):
                raise TypeError(f"{row_where}.config must be a str")
            if row["config"] != config:
                raise ValueError(
                    f"{row_where}.config must be {config!r} for its "
                    "config-then-scenario position"
                )
            if not isinstance(row["scenario"], str):
                raise TypeError(f"{row_where}.scenario must be a str")
            if row["scenario"] != scenario:
                raise ValueError(
                    f"{row_where}.scenario must be {scenario!r} for its "
                    "config-then-scenario position"
                )

            for rank_name in ("baseline_rank", "rank"):
                rank_value = row[rank_name]
                if rank_value is not None and (
                    not isinstance(rank_value, int) or isinstance(rank_value, bool)
                ):
                    raise TypeError(
                        f"{row_where}.{rank_name} must be a non-bool int or None"
                    )

            baseline_rank = row["baseline_rank"]
            rank = row["rank"]
            delta = row["delta"]
            if delta is not None and (
                not isinstance(delta, int) or isinstance(delta, bool)
            ):
                raise TypeError(
                    f"{row_where}.delta must be a non-bool int or None"
                )
            if baseline_rank is None or rank is None:
                if delta is not None:
                    raise ValueError(
                        f"{row_where}.delta must be None when either rank is None"
                    )
            else:
                valid_total += 1
                if delta != rank - baseline_rank:
                    raise ValueError(
                        f"{row_where}.delta must equal rank - baseline_rank"
                    )

            row_index += 1

    transitions = result["transitions"]
    if not isinstance(transitions, list):
        raise TypeError(f"{where}.transitions must be a list")
    previous_pair: tuple[int, int] | None = None
    transition_total = 0
    for index, group in enumerate(transitions):
        group_where = f"{where}.transitions[{index}]"
        if not isinstance(group, dict):
            raise TypeError(f"{group_where} must be a dict")
        if tuple(group.keys()) != _RANK_TRANSITIONS_GROUP_KEYS:
            raise ValueError(
                f"{group_where} must have exactly the keys baseline_rank, rank, "
                "count in order"
            )
        for field in ("baseline_rank", "rank", "count"):
            value = group[field]
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError(f"{group_where}.{field} must be a non-bool int")
            if value < 1:
                raise ValueError(f"{group_where}.{field} must be positive")
        pair = (group["baseline_rank"], group["rank"])
        if previous_pair is not None and pair <= previous_pair:
            raise ValueError(
                f"{where}.transitions must be sorted by ascending "
                "(baseline_rank, rank) with no duplicate pairs"
            )
        previous_pair = pair
        transition_total += group["count"]

    if transition_total != valid_total:
        raise ValueError(
            f"{where}.transitions counts must sum to the number of data rows "
            "with both ranks present"
        )

    return baseline, configs, scenarios, data


def rank_transition_summary(result) -> dict:
    """Summarize composite rank transitions per perturbation configuration.

    ``result`` must be a complete :func:`rank_transitions` result (schema
    ``climate-grid/rank-transitions-v1``) with exactly the keys ``schema,
    baseline, configs, scenarios, data, transitions`` in that order; every
    member is validated against that contract, including the flat
    config-then-scenario ``data`` row order, each row's key order ``config,
    scenario, baseline_rank, rank, delta``, the rank/delta consistency
    (``delta`` is ``rank - baseline_rank`` when both ranks are not ``None``
    and ``None`` otherwise) and the ``transitions`` groups (key order
    ``baseline_rank, rank, count``; non-bool positive ints; sorted by
    ascending ``(baseline_rank, rank)``; counts summing to the number of
    data rows with both ranks present).

    For every perturbation configuration (in configuration order),
    ``total`` is the number of scenarios, ``valid`` is the number of data
    rows whose baseline rank and perturbation rank are both not ``None``
    and ``stable`` is the number of those rows with equal ranks.  When
    ``valid`` is zero, ``stable_rate`` is ``None``; otherwise it is
    ``stable / valid``.  The rows with both ranks present are counted by
    their ``(baseline_rank, rank)`` pair and the groups are sorted by the
    pair in ascending order; each group's ``rate`` is ``count / valid``.

    The returned mapping uses the key order ``schema, baseline, configs,
    scenarios, data, transitions``; ``schema`` is
    ``climate-grid/rank-transition-summary-v1`` and ``baseline``,
    ``configs`` and ``scenarios`` echo the input arrays.  ``data`` follows
    the configuration order; each row uses the key order ``config, total,
    valid, stable, stable_rate``.  ``transitions`` is a flat list in
    configuration-then-pair order; each row uses the key order ``config,
    baseline_rank, rank, count, rate``.  The counts and ranks are non-bool
    ints, the rates are floats or ``None`` and every output float is
    ``round(x, 12)`` with negative zero normalized to ``0.0``.  Inputs are
    not modified.

    Raises ``TypeError`` for wrong container/item/argument types and
    ``ValueError`` for any other contract violation.
    """
    baseline, configs, scenarios, data = _validate_rank_transitions(result)

    n_scenarios = len(scenarios)
    summary_data = []
    summary_transitions = []
    for config_index, config in enumerate(configs):
        rows = data[
            config_index * n_scenarios : (config_index + 1) * n_scenarios
        ]
        valid_rows = [
            row
            for row in rows
            if row["baseline_rank"] is not None and row["rank"] is not None
        ]
        valid = len(valid_rows)
        stable = sum(
            1 for row in valid_rows if row["baseline_rank"] == row["rank"]
        )
        stable_rate = None if valid == 0 else _round_output(stable / valid)
        summary_data.append(
            {
                "config": config,
                "total": n_scenarios,
                "valid": valid,
                "stable": stable,
                "stable_rate": stable_rate,
            }
        )

        pair_counts: dict[tuple[int, int], int] = {}
        for row in valid_rows:
            pair = (row["baseline_rank"], row["rank"])
            pair_counts[pair] = pair_counts.get(pair, 0) + 1
        for (baseline_rank, rank), count in sorted(pair_counts.items()):
            summary_transitions.append(
                {
                    "config": config,
                    "baseline_rank": baseline_rank,
                    "rank": rank,
                    "count": count,
                    "rate": _round_output(count / valid),
                }
            )

    return {
        "schema": _RANK_TRANSITION_SUMMARY_SCHEMA,
        "baseline": baseline,
        "configs": list(configs),
        "scenarios": list(scenarios),
        "data": summary_data,
        "transitions": summary_transitions,
    }


